struct Envio {
    destino: String,
}

impl Drop for Envio {
    fn drop(&mut self) {
        println!("  se libera el envío a {}", self.destino);
    }
}

fn entregar(e: Envio) {
    println!("  entregando a {}", e.destino);
}   // acá termina entregar: su dueño, e, sale de alcance

fn main() {
    let a = Envio { destino: String::from("Flores") };
    println!("creado");
    entregar(a);
    println!("de vuelta en main");
}

