fn contar_paradas(paradas: &Vec<String>) -> usize {
    paradas.len()          // solo mira: no se lo queda ni lo cambia
}

fn agregar(paradas: &mut Vec<String>, nueva: &str) {
    paradas.push(String::from(nueva));   // puede modificar, pero nadie más lo está mirando
}

fn main() {
    let mut paradas = vec![String::from("Palermo")];
    println!("antes: {}", contar_paradas(&paradas));
    agregar(&mut paradas, "Flores");
    println!("después: {}", contar_paradas(&paradas));
    println!("la lista sigue siendo mía: {:?}", paradas);
}

fn main() {
    let mut paradas = vec![String::from("Palermo")];
    for p in &paradas {                          // recorrer = prestar la lista para leer
        if p == "Palermo" {
            paradas.push(String::from("Flores"));   // agregar en medio del recorrido
        }
    }
    println!("{:?}", paradas);
}

