use std::fs;

// VmRSS: memoria física que el proceso ocupa ahora (lo lee de /proc/self/status)
fn rss_kib() -> u64 {
    let estado = fs::read_to_string("/proc/self/status").unwrap();
    for linea in estado.lines() {
        if let Some(resto) = linea.strip_prefix("VmRSS:") {
            return resto.trim().trim_end_matches(" kB").trim().parse().unwrap();
        }
    }
    0
}

fn procesar_pedido(n: u8) -> usize {
    let buffer = vec![n; 1 << 20];     // pide 1 MiB y lo llena
    buffer.iter().map(|&b| b as usize).sum::<usize>() % 7
}   // acá buffer sale de alcance y su memoria se devuelve sola

fn main() {
    println!("al empezar: {} KiB", rss_kib());
    let mut acumulado = 0;
    for i in 1..=200u32 {
        acumulado += procesar_pedido(i as u8);
        if i % 50 == 0 {
            println!("tras {:3} pedidos: {} KiB", i, rss_kib());
        }
    }
    println!("(resultado para que no se optimice: {})", acumulado);
}

use std::thread;

fn main() {
    let mut total = 0;
    thread::scope(|s| {
        s.spawn(|| { for _ in 0..1000 { total += 1; } });
        s.spawn(|| { for _ in 0..1000 { total += 1; } });
    });
    println!("total: {}", total);
}
